from modele import C,E

C('Additionner en colonnes','Calcul','Dès P1',
 'Je pose une addition et j’explique les échanges.','Papier quadrillé et matériel de numération.',
 'Réunis 2 786 et 1 457 avec le matériel. Échange dix unités contre une dizaine, puis dix dizaines contre une centaine. Écris chaque étape.',
 ['Les unités s’alignent sous les unités et les autres rangs aussi.','Je commence à droite. Une retenue représente un échange vers le rang suivant.','Les nombres ajoutés sont les termes. Le résultat est la somme.'],
 '2 786 + 1 457 : 13 unités, puis 14 dizaines avec la retenue, puis 12 centaines, puis 4 milliers. Somme : 4 243.',('add4',[2786,1457]),
 'Pose 1 685 + 2 247. Estime la somme avant de calculer.','Environ 4 000 ; somme exacte : 3 932.',[
 E('Pose et calcule 2 134 + 1 425.','3 559.',('blank4',2),'2134+1425==3559'),
 E('Pose et calcule 3 678 + 2 547.','6 225.',None,'3678+2547==6225'),
 E('Pose et calcule 4 006 + 875.','4 881. Le 5 est sous le 6.',None,'4006+875==4881'),
 E('Pose et calcule 1 485 + 276 + 2 039.','3 800.',('blank4',3),'1485+276+2039==3800'),
 E('Pose et calcule 6 579 + 2 421.','9 000.',None,'6579+2421==9000'),
 E('Calcule 7 998 + 2. Choisis la méthode la plus courte.','8 000 ; le calcul mental suffit.',None,'7998+2==8000'),
 E('Deux écoles ont 1 785 et 2 468 livres. Combien de livres ont-elles ensemble ?','1 785 + 2 468 = 4 253 livres.',None,'1785+2468==4253'),
 E('Une collecte réunit 2 768 bouchons lundi, 1 957 mardi et 875 mercredi. Quel est le total ?','2 768 + 1 957 + 875 = 5 600 bouchons.',None,'2768+1957+875==5600'),
 E('Pour 3 486 + 57, Noé place le 5 sous le 3. Corrige la disposition et calcule.','Le 5 des dizaines doit être sous le 8, le 7 sous le 6. Somme : 3 543.',None,'3486+57==3543')],
 'Faire représenter une retenue par un échange, puis reprendre avec les seuls chiffres.',
 'L’alignement dépend des unités de numération. Une opération simple peut se calculer mentalement.')

C('Soustraire en colonnes','Calcul','Dès P1',
 'Je calcule une différence par échanges et je vérifie.','Matériel de numération et papier quadrillé.',
 'Construis 4 002 pour retirer 1 678. Échange un millier, puis une centaine, puis une dizaine pour disposer d’assez d’unités.',
 ['Je garde la même quantité quand je remplace une unité d’un rang par dix du rang suivant.','Je retire les unités, puis les dizaines, les centaines et les milliers.','Le résultat est la différence. Je la vérifie en ajoutant le nombre retiré.'],
 '4 002 devient 3 milliers, 9 centaines, 9 dizaines et 12 unités. Après retrait de 1 678, il reste 2 324.',('sub4',[4002,1678]),
 'Pose 3 205 - 1 487, puis vérifie.','1 718 ; 1 718 + 1 487 = 3 205.',[
 E('Pose et calcule 5 867 - 2 345.','3 522.',('blank4',-2),'5867-2345==3522'),
 E('Pose et calcule 4 325 - 1 786.','2 539.',None,'4325-1786==2539'),
 E('Pose et calcule 6 004 - 2 758.','3 246. Les échanges traversent les rangs qui contiennent zéro.',None,'6004-2758==3246'),
 E('Pose et calcule 8 000 - 3 486.','4 514.',None,'8000-3486==4514'),
 E('Pose et calcule 7 041 - 876.','6 165.',None,'7041-876==6165'),
 E('Calcule 10 000 - 1, puis 9 998 - 8. Choisis une méthode courte.','9 999 ; 9 990.',None,'10000-1==9999 and 9998-8==9990'),
 E('Un magasin a 3 204 enveloppes. Il en vend 1 875. Combien lui en reste-t-il ?','3 204 - 1 875 = 1 329 enveloppes.',None,'3204-1875==1329'),
 E('La distance totale est de 2 450 m. On a parcouru 1 675 m. Quelle distance reste à parcourir ?','2 450 - 1 675 = 775 m.',None,'2450-1675==775'),
 E('Lina trouve 4 002 - 1 678 = 3 324. Utilise une addition pour vérifier et corriger.','3 324 + 1 678 = 5 002 ; c’est trop. La différence correcte est 2 324.',None,'3324+1678==5002 and 4002-1678==2324')],
 'Reprendre les échanges sur un tableau de rangs. Nommer le rang donné et le rang reçu.',
 'Ce livre garde la méthode par échanges ; adapter son usage à la méthode commune de l’école sans mélanger les écritures.')

C('Calculer par compensation','Calcul mental','P1-P2 puis reprises',
 'Je choisis un détour simple pour ajouter ou retrancher.','Ardoise et bande numérique.',
 'Pars de 1 246. Ajoute 38 en ajoutant d’abord 40. De combien faut-il corriger ? Essaie ensuite de retirer 29.',
 ['Pour ajouter 8, 18, 28 ou 38, je peux ajouter 10, 20, 30 ou 40 puis enlever 2.','Pour ajouter 9, 19, 29 ou 39, je peux ajouter la dizaine suivante puis enlever 1.','Pour retirer 9, 19, 29 ou 39, je peux retirer 10, 20, 30 ou 40 puis ajouter 1.'],
 '1 246 + 38 : 1 246 + 40 = 1 286 ; 1 286 - 2 = 1 284.',('compensation',[1246,40,-2]),
 'Calcule 2 305 - 29 en deux étapes.','2 305 - 30 = 2 275 ; 2 275 + 1 = 2 276.',[
 E('Explique le détour du schéma, puis donne le calcul de départ.','On ajoute 20 puis on retire 2 : 2 347 + 18 = 2 365.',('compensation',[2347,20,-2]),'2347+18==2365'),
 E('Calcule : 1 475 + 8 ; 3 206 + 28 ; 4 582 + 38.','1 483 ; 3 234 ; 4 620.',None,'1475+8==1483 and 3206+28==3234 and 4582+38==4620'),
 E('Calcule : 2 368 + 9 ; 5 407 + 19 ; 6 291 + 39.','2 377 ; 5 426 ; 6 330.',None,'2368+9==2377 and 5407+19==5426 and 6291+39==6330'),
 E('Calcule : 1 504 - 9 ; 3 207 - 19 ; 6 432 - 29.','1 495 ; 3 188 ; 6 403.',None,'1504-9==1495 and 3207-19==3188 and 6432-29==6403'),
 E('Calcule : 4 001 - 39 ; 2 478 + 29 ; 7 125 + 18.','3 962 ; 2 507 ; 7 143.',None,'4001-39==3962 and 2478+29==2507 and 7125+18==7143'),
 E('Complète : 2 875 + … = 2 900 ; 6 400 - … = 6 371.','25 ; 29.',None,'2875+25==2900 and 6400-29==6371'),
 E('Une médiathèque possède 3 487 livres et en reçoit 38. Combien en a-t-elle ?','3 487 + 40 = 3 527 ; 3 527 - 2 = 3 525 livres.',None,'3487+38==3525'),
 E('Une réserve de 2 604 feuilles diminue de 19 feuilles. Quel est le nouveau stock ?','2 604 - 20 = 2 584 ; 2 584 + 1 = 2 585 feuilles.',None,'2604-19==2585'),
 E('Noé retire 30 puis encore 1 pour calculer 1 450 - 29. Explique et corrige.','Retirer 30 enlève un de trop : il faut ajouter 1. Résultat : 1 421.',None,'1450-29==1421')],
 'Autoriser les étapes sur l’ardoise, puis les alléger quand le détour est compris.',
 'Faire expliquer le sens de la correction. Un calcul mental et ses résultats restent dans le champ jusqu’à 10 000.')

C('Tables, facteurs et multiples','Calcul','Dès P1, toute l’année',
 'Je retrouve les produits et je reconnais des multiples.','Jetons et tableau des tables.',
 'Construis un rectangle de 6 rangées de 8 jetons. Tourne la feuille et explique pourquoi 6 × 8 et 8 × 6 donnent le même nombre.',
 ['Les nombres multipliés sont les facteurs. Le résultat est le produit.','Un multiple de 6 est le résultat de 6 multiplié par un entier : 0, 6, 12, 18…','Les tables se lisent dans les deux sens : 7 × 8 = 56, donc 7 × … = 56 se complète par 8.'],
 '8 × 7 = 8 × 5 + 8 × 2 = 40 + 16 = 56. Je peux retrouver un produit oublié.',('array',[6,8]),
 'Complète 9 × … = 63 et nomme les facteurs.','7 ; les facteurs sont 9 et 7, le produit est 63.',[
 E('Écris les deux multiplications représentées par le rectangle.','4 × 7 = 28 et 7 × 4 = 28.',('array',[4,7]),'4*7==28'),
 E('Calcule : 7 × 8 ; 6 × 9 ; 8 × 8 ; 9 × 7.','56 ; 54 ; 64 ; 63.',None,'7*8==56 and 6*9==54 and 8*8==64 and 9*7==63'),
 E('Complète : 6 × … = 42 ; … × 8 = 72 ; 56 = 7 × … .','7 ; 9 ; 8.',None,'6*7==42 and 9*8==72 and 7*8==56'),
 E('Parmi 18, 25, 30, 42 et 49, relève les multiples de 6.','18, 30 et 42.',None,'18%6==0 and 30%6==0 and 42%6==0'),
 E('Calcule : 1 × 47 ; 0 × 83 ; 10 × 9 ; 5 × 10.','47 ; 0 ; 90 ; 50.',None,'1*47==47 and 0*83==0 and 10*9==90 and 5*10==50'),
 E('Distingue facteur et produit dans 9 × 4 = 36. Est-ce que 36 est un multiple de 9 ?','9 et 4 sont les facteurs ; 36 est le produit. Oui, 36 est un multiple de 9.'),
 E('Sept sacs contiennent chacun 9 pommes. Combien de pommes en tout ?','7 × 9 = 63 pommes.',None,'7*9==63'),
 E('Explique pourquoi 48 est un nombre pair, puis donne un multiple impair de 3.','48 = 2 × 24, donc il est pair. Par exemple 9, qui vaut 3 × 3.'),
 E('Lina dit que 7 × 8 vaut 7 × 7 + 1. Corrige son raisonnement.','Il faut ajouter un groupe de 7 : 7 × 7 + 7 = 49 + 7 = 56.',None,'7*7+7==56')],
 'Revenir aux groupes et utiliser un produit connu comme appui. Varier l’ordre des questions.',
 'Multiplier par zéro donne zéro. Les deux facteurs jouent des rôles différents dans une histoire même si le produit est commutatif.')

C('Doubles, moitiés et repères de 60','Calcul mental','P1-P3 puis reprises',
 'Je mémorise des faits utiles et je les relie entre eux.','Cartes de faits numériques et jetons.',
 'Partage 150 en deux parts égales en séparant 100 et 50. Puis cherche toutes les façons d’organiser 60 jetons en rangées complètes.',
 ['Le double correspond à deux parts égales ; la moitié permet de retrouver une de ces parts.','Pour prendre la moitié d’une somme, je peux partager chaque partie en deux.','Je connais les multiples de 25 jusqu’à 100 et les produits qui donnent 60.'],
 'La moitié de 150 : moitié de 100 = 50 ; moitié de 50 = 25 ; 50 + 25 = 75.',('halftree',[150,100,50]),
 'Trouve le double de 75, puis complète 4 × … = 60.','150 ; 15.',[
 E('Donne les doubles de 18, 35, 60 et 75.','36 ; 70 ; 120 ; 150.',None,'2*18==36 and 2*35==70 and 2*60==120 and 2*75==150'),
 E('Donne les moitiés de 36, 90, 120 et 150.','18 ; 45 ; 60 ; 75.',None,'36//2==18 and 90//2==45 and 120//2==60 and 150//2==75'),
 E('Donne les doubles de 250, 400 et 600, puis la moitié de 1 200.','500 ; 800 ; 1 200 ; 600.',None,'2*250==500 and 2*400==800 and 2*600==1200 and 1200//2==600'),
 E('Complète : 25 ; 50 ; … ; 100. Écris les quatre produits par 25.','75 ; 1 × 25 = 25 ; 2 × 25 = 50 ; 3 × 25 = 75 ; 4 × 25 = 100.'),
 E('Complète : 2 × … = 60 ; 3 × … = 60 ; 4 × … = 60 ; 5 × … = 60.','30 ; 20 ; 15 ; 12.',None,'2*30==60 and 3*20==60 and 4*15==60 and 5*12==60'),
 E('Écris les produits de deux nombres entiers positifs qui donnent 60, sans répéter les facteurs dans l’autre sens.','1 × 60 ; 2 × 30 ; 3 × 20 ; 4 × 15 ; 5 × 12 ; 6 × 10.'),
 E('Deux classes collectent chacune 75 piles usagées. Combien en collectent-elles ensemble ?','150 piles.',None,'2*75==150'),
 E('On partage équitablement 800 feuilles entre deux classes. Combien chaque classe reçoit-elle ?','400 feuilles.',None,'800//2==400'),
 E('Noé dit que la moitié de 150 est 50. Vérifie avec un double et corrige.','Le double de 50 est 100. La moitié de 150 est 75, car 2 × 75 = 150.',None,'2*75==150')],
 'Faire manipuler deux parts et relier chaque moitié à son double. Reprendre les faits à plusieurs dates.',
 'Les faits s’automatisent avec des rappels espacés ; un temps limité se propose après leur apprentissage.')
